import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadDudhwaData(){const e=readFileSync(resolve(__dirname,"../../frontend/dudhwa-national-park-explorer/dudhwa-data.js"),"utf-8");return new Function(e+"\nreturn { DUDHWA_INFO, TERAI_ECOSYSTEM, SWAMP_DEER_INFO, RHINO_CONSERVATION, TIGERS_WILDLIFE, SAFARI_ZONES, HISTORY_TIMELINE, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadNationalParksData(){const e=readFileSync(resolve(__dirname,"../../frontend/national-parks-explorer/data.js"),"utf-8");return new Function(e+"\nreturn { NATIONAL_PARKS, STATES };")()}function loadSearchIndex(){const e=readFileSync(resolve(__dirname,"../../search-index.js"),"utf-8");return new Function("window",e+"\nreturn window.indiaSearchIndex;")({})}describe("Dudhwa National Park Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadDudhwaData()}),describe("DUDHWA_INFO metadata & TERAI_ECOSYSTEM",()=>{it("contains correct park metadata for Dudhwa",()=>{expect(e.DUDHWA_INFO.id).toBe("dudhwa"),expect(e.DUDHWA_INFO.name).toBe("Dudhwa National Park"),expect(e.DUDHWA_INFO.state).toBe("Uttar Pradesh"),expect(e.DUDHWA_INFO.establishedYear).toBe(1977),expect(e.DUDHWA_INFO.rhinoReintroducedYear).toBe(1984),expect(e.DUDHWA_INFO.coordinates.lat).toBeCloseTo(28.4917,2),expect(e.DUDHWA_INFO.coordinates.lng).toBeCloseTo(80.65,2)}),it("TERAI_ECOSYSTEM details Sal forests, grasslands and oxbow lakes",()=>{expect(e.TERAI_ECOSYSTEM.title).toContain("Terai"),expect(e.TERAI_ECOSYSTEM.salForests).toBeDefined(),expect(e.TERAI_ECOSYSTEM.wetlandsAndLakes).toContain("Bankey Taal")})}),describe("SWAMP_DEER_INFO & RHINO_CONSERVATION",()=>{it("SWAMP_DEER_INFO details Barasingha population and adaptations",()=>{expect(e.SWAMP_DEER_INFO.name).toContain("Barasingha"),expect(e.SWAMP_DEER_INFO.significance).toContain("50%"),expect(e.SWAMP_DEER_INFO.adaptation).toBeDefined()}),it("RHINO_CONSERVATION covers 1984 translocation project",()=>{expect(e.RHINO_CONSERVATION.title).toContain("1984"),expect(e.RHINO_CONSERVATION.translocationDetails).toContain("Kaziranga"),expect(e.RHINO_CONSERVATION.currentStatus).toBeDefined()})}),describe("SAFARI_ZONES & TIGERS_WILDLIFE",()=>{it("contains 4 safari zones",()=>{expect(Array.isArray(e.SAFARI_ZONES)).toBe(!0),expect(e.SAFARI_ZONES.length).toBe(4);const t=e.SAFARI_ZONES.find(e=>"sonaripur"===e.id);expect(t).toBeDefined(),expect(t.type).toContain("Elephant")}),it("TIGERS_WILDLIFE includes Bengal Tiger and Gangetic Dolphin",()=>{expect(Array.isArray(e.TIGERS_WILDLIFE)).toBe(!0),expect(e.TIGERS_WILDLIFE.length).toBeGreaterThanOrEqual(4);const t=e.TIGERS_WILDLIFE.find(e=>"bengal-tiger"===e.id);expect(t).toBeDefined()})}),describe("MAP_HOTSPOTS & HISTORY_TIMELINE",()=>{it("MAP_HOTSPOTS has valid percentage coordinates (0-100)",()=>{expect(Array.isArray(e.MAP_HOTSPOTS)).toBe(!0),expect(e.MAP_HOTSPOTS.length).toBeGreaterThanOrEqual(5),e.MAP_HOTSPOTS.forEach(e=>{expect(e.x).toBeGreaterThanOrEqual(0),expect(e.x).toBeLessThanOrEqual(100),expect(e.y).toBeGreaterThanOrEqual(0),expect(e.y).toBeLessThanOrEqual(100)})}),it("HISTORY_TIMELINE includes 1958 sanctuary and 1977 national park",()=>{expect(Array.isArray(e.HISTORY_TIMELINE)).toBe(!0),expect(e.HISTORY_TIMELINE.length).toBeGreaterThanOrEqual(4)})}),describe("Landing Page & Search Index Integration",()=>{it("Dudhwa entry in NATIONAL_PARKS has explorerUrl",()=>{const e=loadNationalParksData().NATIONAL_PARKS.find(e=>"dudhwa"===e.id);expect(e).toBeDefined(),expect(e.explorerUrl).toBe("../dudhwa-national-park-explorer/index.html"),expect(e.state).toBe("Uttar Pradesh")}),it("Search Index registers Dudhwa National Park Explorer",()=>{const e=loadSearchIndex().find(e=>"Dudhwa National Park Explorer"===e.title);expect(e).toBeDefined(),expect(e.url).toBe("frontend/dudhwa-national-park-explorer/index.html")})})});